import byTypeFilenameGenerator from '../filename-generator/by-type.js';

class GenerateFilenameByTypePlugin {
  apply(registerAction) {
    let occupiedFilenames = {}, subdirectories = null, defaultFilename = 'index.html';
    
    registerAction('generateFilename', async ({resource}) => {
      let superParentResource = resource;
      while (superParentResource && superParentResource.parent) {
        superParentResource = superParentResource.parent
      }

      const matchResPid = superParentResource.url.match(/\?[^#]*[&?]curid=(\d+)/);
      const pageId = matchResPid[1];

      const matchRedOid = superParentResource.url.match(/\?[^#]*[&?]oldid=(\d+)/);
      const oldId = matchRedOid[1]

      const key = `${pageId}_${oldId}`;

      occupiedFilenames[key] = occupiedFilenames[key] || [];
      const filename = byTypeFilenameGenerator(resource, {subdirectories, defaultFilename}, occupiedFilenames[key]);
      occupiedFilenames[key].push(filename);

      // Manually fixing the file names of critical js and css resources required to render a crawled wikipage properly.
      // Due to the way wikipedia has implemented how it obtains these resources, they will all have a .php extension
      // if not fixed manually and browser won't identify them when rendering.
      if (!resource.filename && resource.url.indexOf('load.php') >= 0) {
        if(resource.type === 'js' )
          return {filename: `${key}/${filename.replace('php', 'js')}`};
        if(resource.type === 'css')
          return {filename: `${key}/${filename.replace('php', 'css')}`};
      }
      return {filename: `${key}/${filename}`};
    })
  }
}


